contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, bool freeze) public payable {
        bool setupReverted;
        c.freezeAccount(target, freeze); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setupReverted = true;
        } else {
            setupReverted = false;
        }
        require(!setupReverted);
        bool currentStatus = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.freezeAccount(target, currentStatus); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(!secondReverted && c.frozenAccount(target) == currentStatus);
    }
}

